using Newtonsoft.Json.Linq;

namespace E33ModEditor.Core.Loot;

/// <summary>
/// Weapon-effect archetypes: coherent effect groups plus sibling links used by
/// the passive randomizer. Stock lives in
/// <c>Loot/Data/weapon_effect_archetypes.json</c> (generated by
/// <c>Planning/archetypes/build_archetypes.py</c>); the <c>work/</c> overlay wins
/// when present, same pattern as tiers/characters.
/// </summary>
public sealed class WeaponEffectArchetypes
{
    public sealed class Archetype
    {
        public required string Id { get; init; }
        public required string Name { get; init; }
        public string Group { get; init; } = "";
        public string? Element { get; init; }
        public string Description { get; init; } = "";
        public IReadOnlyList<string> Links { get; init; } = Array.Empty<string>();
        public IReadOnlyList<string> Members { get; init; } = Array.Empty<string>();
    }

    private readonly List<Archetype> _list = new();
    private readonly Dictionary<string, Archetype> _byId = new(StringComparer.Ordinal);
    private readonly Dictionary<string, List<string>> _links = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _elementByEffect = new(StringComparer.Ordinal);
    private string _raw = "{\"archetypes\":[]}";

    public IReadOnlyList<Archetype> All => _list;

    public IReadOnlyList<string> Members(string id) =>
        _byId.TryGetValue(id, out var a) ? a.Members : Array.Empty<string>();

    public IReadOnlyList<string> Links(string id) =>
        _links.TryGetValue(id, out var l) ? l : Array.Empty<string>();

    public Archetype? Get(string id) => _byId.TryGetValue(id, out var a) ? a : null;

    /// <summary>Stain element gate: Fire/Ice/…/Dark for element-specific stain
    /// effects, null for everything else.</summary>
    public string? ElementOf(string effectId) =>
        _elementByEffect.TryGetValue(effectId, out var e) ? e : null;

    public static string OverlayPath =>
        Path.Combine(EditorPaths.RepoRoot, "work", "weapon_effect_archetypes.json");

    public static string StockSourcePath =>
        Path.Combine(EditorPaths.RepoRoot, "src", "E33ModEditor.Core", "Loot", "Data",
            "weapon_effect_archetypes.json");

    public static WeaponEffectArchetypes Load()
    {
        var a = new WeaponEffectArchetypes();
        a.ResetToStock();
        if (File.Exists(OverlayPath))
        {
            try { a.ReplaceFromJson(File.ReadAllText(OverlayPath)); }
            catch { /* keep stock */ }
        }
        return a;
    }

    public void ResetToStock() => ReplaceFromJson(ReadStock());

    public void ReplaceFromJson(string json)
    {
        var root = JObject.Parse(json);
        var list = new List<Archetype>();
        var links = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        var elements = new Dictionary<string, string>(StringComparer.Ordinal);

        foreach (var t in root["archetypes"] as JArray ?? new JArray())
        {
            var id = (string?)t["id"] ?? "";
            if (id.Length == 0) continue;
            var linkList = (t["links"] as JArray)?
                .Select(x => (string?)x ?? "")
                .Where(x => x.Length > 0)
                .Distinct(StringComparer.Ordinal)
                .ToList() ?? new List<string>();
            var members = new List<string>();
            foreach (var m in t["members"] as JArray ?? new JArray())
            {
                var mid = (string?)m["id"] ?? "";
                if (mid.Length == 0) continue;
                members.Add(mid);
                var el = (string?)m["element"];
                if (!string.IsNullOrEmpty(el)) elements[mid] = el;
            }
            list.Add(new Archetype
            {
                Id = id,
                Name = (string?)t["name"] ?? id,
                Group = (string?)t["group"] ?? "",
                Element = (string?)t["element"],
                Description = (string?)t["desc"] ?? "",
                Links = linkList,
                Members = members.Distinct(StringComparer.Ordinal).ToList(),
            });
            links[id] = linkList;
        }

        // Symmetric closure, dropping links to unknown archetypes.
        var known = new HashSet<string>(list.Select(a => a.Id), StringComparer.Ordinal);
        foreach (var a in list)
        {
            links[a.Id] = links[a.Id].Where(known.Contains).Distinct(StringComparer.Ordinal).ToList();
            foreach (var l in links[a.Id])
                if (links.TryGetValue(l, out var back) && !back.Contains(a.Id))
                    back.Add(a.Id);
        }

        var rebuilt = list.Select(a => new Archetype
        {
            Id = a.Id, Name = a.Name, Group = a.Group, Element = a.Element,
            Description = a.Description, Links = links[a.Id], Members = a.Members,
        }).ToList();

        _list.Clear();
        _list.AddRange(rebuilt);
        _byId.Clear();
        foreach (var a in rebuilt) _byId[a.Id] = a;
        _links.Clear();
        foreach (var (k, v) in links) _links[k] = v;
        _elementByEffect.Clear();
        foreach (var (k, v) in elements) _elementByEffect[k] = v;
        _raw = json;
    }

    public string ToJson() => _raw;

    public void Save()
    {
        var json = ToJson();
        Directory.CreateDirectory(Path.GetDirectoryName(OverlayPath)!);
        File.WriteAllText(OverlayPath, json);
        try
        {
            var dir = Path.GetDirectoryName(StockSourcePath);
            if (!string.IsNullOrEmpty(dir) && Directory.Exists(dir))
                File.WriteAllText(StockSourcePath, json);
        }
        catch { /* packed install */ }
    }

    private static string ReadStock()
    {
        var asm = typeof(WeaponEffectArchetypes).Assembly;
        var name = asm.GetManifestResourceNames()
            .First(n => n.EndsWith("weapon_effect_archetypes.json", StringComparison.OrdinalIgnoreCase));
        using var s = asm.GetManifestResourceStream(name)!;
        using var r = new StreamReader(s);
        return r.ReadToEnd();
    }
}
